  1	/**
  2	 * Unit tests for the "Open" button (Actions column) added to the repository
  3	 * status table in workspace-detail.js — WP-005.
  4	 *
  5	 * Covers:
  6	 *   - 4th column header labelled "Actions" is present in the table.
  7	 *   - Each repository row has a 4th cell with a button styled
  8	 *     `btn btn-secondary btn-sm`.
  9	 *   - Clicking the button calls `api.workspaces.openGithubDesktop(projectId, wid, repoId)`.
 10	 *   - When the API call rejects, the button is re-enabled (error path).
 11	 *   - Cell index 2 remains the badge cell (Actions column at index 3 does not
 12	 *     shift existing indices, so updateStatusTable continues to work).
 13	 *
 14	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 15	 * Run individually with:
 16	 *   node --test gui/public/js/views/workspace-detail.open-button.test.mjs
 17	 */
 18	
 19	import { test, beforeEach } from 'node:test';
 20	import assert from 'node:assert/strict';
 21	import { JSDOM } from 'jsdom';
 22	
 23	// ---------------------------------------------------------------------------
 24	// jsdom setup — install globals before any module is loaded
 25	// ---------------------------------------------------------------------------
 26	
 27	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="app"></div></body></html>', {
 28	    url: 'http://localhost/',
 29	});
 30	
 31	const { window } = dom;
 32	
 33	globalThis.document    = window.document;
 34	globalThis.window      = window;
 35	globalThis.location    = window.location;
 36	globalThis.HTMLElement = window.HTMLElement;
 37	// CSS.escape shim (jsdom may not expose CSS global)
 38	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 39	
 40	// Stub setInterval / clearInterval so the polling loop never fires and the
 41	// process exits cleanly after tests complete.
 42	let _intervalId = 0;
 43	const _intervals = new Map();
 44	globalThis.setInterval = (fn, delay) => {
 45	    const id = ++_intervalId;
 46	    _intervals.set(id, { fn, delay });
 47	    return id;
 48	};
 49	globalThis.clearInterval = (id) => {
 50	    _intervals.delete(id);
 51	};
 52	
 53	// ---------------------------------------------------------------------------
 54	// Minimal fetch mock (required by api.js)
 55	// ---------------------------------------------------------------------------
 56	
 57	globalThis.fetch = async () => ({
 58	    status: 200,
 59	    ok: true,
 60	    statusText: 'OK',
 61	    headers: { get: () => 'application/json' },
 62	    json: async () => ({}),
 63	});
 64	
 65	// ---------------------------------------------------------------------------
 66	// Import dependencies and patch api
 67	// ---------------------------------------------------------------------------
 68	
 69	const { api } = await import('../api.js');
 70	
 71	/** Calls recorded by the openGithubDesktop spy. */
 72	const ghDesktopCalls = [];
 73	let ghDesktopShouldFail  = false;
 74	let ghDesktopFailMessage = 'GitHub Desktop not found';
 75	
 76	// Patch openGithubDesktop on the live api object.
 77	api.workspaces.openGithubDesktop = async (projectId, wid, repoId) => {
 78	    ghDesktopCalls.push({ projectId, wid, repoId });
 79	    if (ghDesktopShouldFail) {
 80	        throw new Error(ghDesktopFailMessage);
 81	    }
 82	    return { success: true };
 83	};
 84	
 85	// Stub the remaining api calls used by renderWorkspaceDetail.
 86	api.workspaces.get    = async () => ({ Id: 'DEV', id: 'DEV', Description: '', initialized: true, folderPath: '/tmp/dev' });
 87	api.workspaces.health = async () => ({ healthy: true, issues: [] });
 88	api.projects.get      = async () => ({ Id: 'my-project', Repositories: ['repo-alpha', 'repo-beta'] });
 89	api.status.refresh    = async () => ({
 90	    'repo-alpha': { currentBranch: 'main', localCommits: 0, unfetchedCommits: 0, modifiedFiles: 0, lastActivity: null, hasConflicts: false },
 91	    'repo-beta':  { currentBranch: 'dev',  localCommits: 1, unfetchedCommits: 0, modifiedFiles: 2, lastActivity: null, hasConflicts: false },
 92	});
 93	api.status.get = api.status.refresh;
 94	if (!api.config)          api.config          = {};
 95	if (!api.config.polling)  api.config.polling  = {};
 96	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
 97	
 98	const { renderWorkspaceDetail } = await import('./workspace-detail.js');
 99	
100	// ---------------------------------------------------------------------------

101	// Loading helper
102	// ---------------------------------------------------------------------------
103	
104	/**
105	 * Render a loading spinner into `el`.
106	 *
107	 * @param {HTMLElement} el
108	 * @param {string} [label]
109	 */
110	function showLoading(el, label = 'Loading…') {
111	    el.innerHTML = '';
112	    const wrapper = document.createElement('div');
113	    wrapper.className = 'loading-indicator';
114	    wrapper.setAttribute('aria-live', 'polite');
115	
116	    const spinner = document.createElement('span');
117	    spinner.className = 'spinner';
118	    spinner.setAttribute('aria-hidden', 'true');
119	    wrapper.appendChild(spinner);
120	
121	    const labelEl = document.createElement('span');
122	    labelEl.textContent = label;
123	    wrapper.appendChild(labelEl);
124	
125	    el.appendChild(wrapper);
126	}
127	
128	// ---------------------------------------------------------------------------
129	// Setup helper
130	// ---------------------------------------------------------------------------
131	
132	/**
133	 * Run workspace setup and show appropriate toast notification.
134	 *
135	 * @param {string} projectId
136	 * @param {string} workspaceId
137	 * @param {string} successMessage - Toast message shown when all repos succeed.
138	 * @returns {Promise<Object>} The setup result from the API.
139	 * @throws {Error} Re-throws API errors for the caller to handle.
140	 */
141	async function runSetup(projectId, workspaceId, successMessage) {
142	    const result = await api.workspaces.setup(projectId, workspaceId);
143	    const failures = (result && result.results || []).filter((r) => !r.success);
144	    if (failures.length > 0) {
145	        const names = failures.map((f) => f.repositoryId).join(', ');
146	        showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
147	    } else {
148	        showToast(successMessage, 'success');
149	    }
150	    return result;
151	}
152	
153	// ---------------------------------------------------------------------------
154	// Status table helpers
155	// ---------------------------------------------------------------------------
156	
157	/**
158	 * Build the status `<tbody>` row for a single repository.
159	 *
160	 * The row uses `data-repo-id` on the badge container so the polling update
161	 * can locate and replace badge contents in-place.
162	 *
163	 * @param {string} repoId
164	 * @param {string} repoName
165	 * @param {Object|null} statusInfo - GitStatusInfo or null.
166	 * @param {string} projectId - Project ID, used by the "Open" button.
167	 * @param {string} wid - Workspace ID, used by the "Open" button.
168	 * @returns {HTMLTableRowElement}
169	 */
170	function buildRepoStatusRow(repoId, repoName, statusInfo, projectId, wid) {
171	    const tr = document.createElement('tr');
172	    tr.dataset.repoId = repoId;
173	
174	    // Repository name / ID
175	    const nameCell = document.createElement('td');
176	    nameCell.className = 'repo-name-cell';
177	    const nameEl = document.createElement('span');
178	    nameEl.className = 'repo-name';
179	    nameEl.textContent = repoName;
180	    if (repoName !== repoId) {
181	        const idHint = document.createElement('span');
182	        idHint.className = 'text-muted repo-id-hint';
183	        idHint.textContent = ` (${repoId})`;
184	        nameEl.appendChild(idHint);
185	    }
186	    nameCell.appendChild(nameEl);
187	    tr.appendChild(nameCell);
188	
189	    // Branch name
190	    const branchCell = document.createElement('td');
191	    branchCell.className = 'repo-branch-cell';
192	    branchCell.textContent = (statusInfo && statusInfo.currentBranch)
193	        ? statusInfo.currentBranch
194	        : '—';
195	    tr.appendChild(branchCell);
196	
197	    // Status badge cell (index 2 — must stay at this position)
198	    const badgeCell = document.createElement('td');
199	    badgeCell.className = 'repo-badge-cell';
200	
201	    const badgeWrapper = document.createElement('div');
202	    badgeWrapper.dataset.repoId = repoId;
203	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
204	    badgeCell.appendChild(badgeWrapper);
205	    tr.appendChild(badgeCell);
206	
207	    // Actions cell (index 3) — "Open" button for GitHub Desktop
208	    const actionsCell = document.createElement('td');
209	    actionsCell.className = 'repo-actions-cell';
210	
211	    const openBtn = document.createElement('button');
212	    openBtn.type      = 'button';
213	    openBtn.className = 'btn btn-secondary btn-sm';
214	    openBtn.textContent = 'Open';
215	    openBtn.title = 'Open this repository in GitHub Desktop.';
216	
217	    openBtn.addEventListener('click', async () => {
218	        openBtn.disabled    = true;
219	        openBtn.textContent = 'Opening…';
220	        try {
221	            await api.workspaces.openGithubDesktop(projectId, wid, repoId);
222	        } catch (err) {
223	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
224	        } finally {
225	            openBtn.disabled    = false;
226	            openBtn.textContent = 'Open';
227	        }
228	    });
229	
230	    actionsCell.appendChild(openBtn);
231	    tr.appendChild(actionsCell);
232	
233	    return tr;
234	}
235	
236	/**
237	 * Update an existing status table in-place by replacing badge contents and
238	 * branch text for each repository whose status has changed.
239	 *
240	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
241	 * wrapper `<div>` inside it. No full re-render of the table is performed.
242	 *
243	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
244	 * @param {Record<string, Object|null>} statusMap - Keyed by repository ID.
245	 */
246	function updateStatusTable(tableBody, statusMap) {
247	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
248	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
249	        if (!row) continue;

101	// Render helper
102	// ---------------------------------------------------------------------------
103	
104	/**
105	 * Render the workspace detail view and wait for the async Promise.all inside
106	 * renderWorkspaceDetail to settle and populate the DOM.
107	 *
108	 * Returns both the container and the cleanup function so callers can stop
109	 * any pending interval.
110	 *
111	 * @param {string} [projectId]
112	 * @param {string} [wid]
113	 * @returns {Promise<{ container: HTMLElement, cleanup: function }>}
114	 */
115	async function renderView(projectId = 'my-project', wid = 'DEV') {
116	    const container = window.document.getElementById('app');
117	    container.innerHTML = '';
118	
119	    const cleanup = renderWorkspaceDetail(container, { id: projectId, wid });
120	
121	    // Wait for the internal async bootstrap to complete (Promise.all).
122	    // We poll until a <table> is present or a maximum wait is reached.
123	    await new Promise((resolve) => {
124	        let ticks = 0;
125	        const poll = () => {
126	            ticks++;
127	            if (container.querySelector('table') || ticks > 100) {
128	                resolve();
129	            } else {
130	                // Use the real (un-stubbed) Promise machinery to defer.
131	                Promise.resolve().then(poll);
132	            }
133	        };
134	        Promise.resolve().then(poll);
135	    });
136	
137	    return { container, cleanup };
138	}
139	
140	// ---------------------------------------------------------------------------
141	// Per-test reset
142	// ---------------------------------------------------------------------------
143	
144	beforeEach(() => {
145	    ghDesktopCalls.length = 0;
146	    ghDesktopShouldFail   = false;
147	    ghDesktopFailMessage  = 'GitHub Desktop not found';
148	    _intervals.clear();
149	});
150	
151	// ---------------------------------------------------------------------------
152	// Tests
153	// ---------------------------------------------------------------------------
154	
155	// AC 1 — 4th column header "Actions"
156	test('status table has a 4th column header labelled "Actions"', async () => {
157	    const { container, cleanup } = await renderView();
158	    try {
159	        const headers = container.querySelectorAll('thead th');
160	        assert.ok(headers.length >= 4, `expected ≥4 <th> elements, got ${headers.length}`);
161	        assert.equal(headers[3].textContent, 'Actions');
162	    } finally {
163	        cleanup();
164	    }
165	});
166	
167	// AC 2 — each row has a 4th cell with btn btn-secondary btn-sm
168	test('each repository row has a 4th cell with a correctly-styled "Open" button', async () => {
169	    const { container, cleanup } = await renderView();
170	    try {
171	        const rows = [...container.querySelectorAll('tbody tr[data-repo-id]')];
172	        assert.ok(rows.length > 0, 'expected at least one repository row');
173	
174	        for (const row of rows) {
175	            assert.ok(row.cells.length >= 4, `expected ≥4 cells, got ${row.cells.length}`);
176	            const btn = row.cells[3].querySelector('button');
177	            assert.ok(btn, 'expected a <button> in cells[3]');
178	            assert.equal(btn.textContent.trim(), 'Open');
179	            assert.ok(btn.classList.contains('btn'),           'missing class "btn"');
180	            assert.ok(btn.classList.contains('btn-secondary'), 'missing class "btn-secondary"');
181	            assert.ok(btn.classList.contains('btn-sm'),        'missing class "btn-sm"');
182	        }
183	    } finally {
184	        cleanup();
185	    }
186	});
187	
188	// AC 3 — clicking "Open" calls api.workspaces.openGithubDesktop with correct args
189	test('clicking "Open" calls openGithubDesktop with projectId, wid, and repoId', async () => {
190	    const { container, cleanup } = await renderView('my-project', 'DEV');
191	    try {
192	        const firstRow = container.querySelector('tbody tr[data-repo-id]');
193	        assert.ok(firstRow, 'expected at least one repository row');
194	
195	        const repoId = firstRow.dataset.repoId;
196	        const btn    = firstRow.cells[3].querySelector('button');
197	        btn.click();
198	
199	        // Drain microtask queue to let the async click handler run.
200	        await new Promise((r) => Promise.resolve().then(r));
201	        await new Promise((r) => Promise.resolve().then(r));
202	
203	        assert.equal(ghDesktopCalls.length, 1, 'expected exactly 1 openGithubDesktop call');
204	        assert.equal(ghDesktopCalls[0].projectId, 'my-project');
205	        assert.equal(ghDesktopCalls[0].wid,       'DEV');
206	        assert.equal(ghDesktopCalls[0].repoId,    repoId);
207	    } finally {
208	        cleanup();
209	    }
210	});
211	
212	// AC 4 — on API failure the button is re-enabled (error path)
213	test('when openGithubDesktop rejects, the button is re-enabled after the error', async () => {
214	    ghDesktopShouldFail  = true;
215	    ghDesktopFailMessage = 'app not installed';
216	
217	    const { container, cleanup } = await renderView();
218	    try {
219	        const firstRow = container.querySelector('tbody tr[data-repo-id]');
220	        const btn      = firstRow.cells[3].querySelector('button');
221	
222	        btn.click();
223	
224	        // Drain enough microtask ticks for try/catch/finally to complete.
225	        for (let i = 0; i < 10; i++) {
226	            await new Promise((r) => Promise.resolve().then(r));
227	        }
228	
229	        assert.equal(btn.disabled,           false,  'button should be re-enabled after error');
230	        assert.equal(btn.textContent.trim(), 'Open', 'button label should be restored after error');
231	        assert.equal(ghDesktopCalls.length,  1,      'API should have been called despite the error');
232	    } finally {
233	        cleanup();
234	    }
235	});
236	
237	// AC 6 — cell index 2 is still the badge cell; Actions column is at index 3
238	test('cells[2] is repo-badge-cell and cells[3] is repo-actions-cell', async () => {
239	    const { container, cleanup } = await renderView();
240	    try {
241	        const firstRow = container.querySelector('tbody tr[data-repo-id]');
242	        assert.ok(firstRow, 'expected at least one repository row');
243	
244	        const badgeCell   = firstRow.cells[2];
245	        const actionsCell = firstRow.cells[3];
246	
247	        assert.ok(badgeCell,   'expected cells[2] to exist');
248	        assert.ok(actionsCell, 'expected cells[3] to exist');
249	
250	        assert.ok(

251	            badgeCell.classList.contains('repo-badge-cell'),
252	            `cells[2] should have class "repo-badge-cell", got "${badgeCell.className}"`,
253	        );
254	        assert.ok(
255	            actionsCell.classList.contains('repo-actions-cell'),
256	            `cells[3] should have class "repo-actions-cell", got "${actionsCell.className}"`,
257	        );
258	    } finally {
259	        cleanup();
260	    }
261	});

251	        // Update branch cell (second cell)
252	        const branchCell = row.cells[1];
253	        if (branchCell) {
254	            branchCell.textContent = (statusInfo && statusInfo.currentBranch)
255	                ? statusInfo.currentBranch
256	                : '—';
257	        }
258	
259	        // Update badge wrapper (third cell → div[data-repo-id])
260	        const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
261	        if (badgeWrapper) {
262	            badgeWrapper.innerHTML = '';
263	            badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
264	        }
265	    }
266	}
267	
268	// ---------------------------------------------------------------------------
269	// Section builders
270	// ---------------------------------------------------------------------------
271	
272	/**
273	 * Build the rename workspace inline form and wire up its event handlers.
274	 *
275	 * @param {string} projectId
276	 * @param {{ id: string }} workspace
277	 * @param {HTMLButtonElement} renameBtn - The "Rename" button that toggles form visibility.
278	 * @returns {HTMLElement}
279	 */
280	function buildRenameForm(projectId, workspace, renameBtn) {
281	    const wrapper = document.createElement('div');
282	    wrapper.className = 'rename-workspace-form-wrapper card';
283	    wrapper.hidden = true;
284	
285	    const formTitle = document.createElement('h4');
286	    formTitle.className   = 'form-section-title';
287	    formTitle.textContent = 'Rename Workspace';
288	    wrapper.appendChild(formTitle);
289	
290	    const newIdField = createFormField('New Workspace ID', 'text', 'newWorkspaceId', {
291	        required:    true,
292	        placeholder: 'e.g. DEV or FEATURE',
293	        hint:        'Must be 2–10 uppercase letters (A-Z only).',
294	    });
295	    wrapper.appendChild(newIdField);
296	
297	    const newIdInput   = newIdField.querySelector('[name="newWorkspaceId"]');
298	    const newIdErrorEl = newIdField.querySelector('.field-error');
299	
300	    const formActions = document.createElement('div');
301	    formActions.className = 'form-actions';
302	
303	    const saveBtn = document.createElement('button');
304	    saveBtn.type      = 'button';
305	    saveBtn.className = 'btn btn-primary btn-sm';
306	    saveBtn.textContent = 'Save';
307	
308	    const cancelFormBtn = document.createElement('button');
309	    cancelFormBtn.type      = 'button';
310	    cancelFormBtn.className = 'btn btn-secondary btn-sm';
311	    cancelFormBtn.textContent = 'Cancel';
312	
313	    formActions.appendChild(saveBtn);
314	    formActions.appendChild(cancelFormBtn);
315	    wrapper.appendChild(formActions);
316	
317	    // Behaviour
318	    renameBtn.addEventListener('click', () => {
319	        wrapper.hidden = false;
320	        if (newIdInput) newIdInput.focus();
321	    });
322	
323	    cancelFormBtn.addEventListener('click', () => {
324	        wrapper.hidden = true;
325	        if (newIdInput) newIdInput.value = '';
326	        if (newIdErrorEl) newIdErrorEl.hidden = true;
327	    });
328	
329	    saveBtn.addEventListener('click', async () => {
330	        if (newIdErrorEl) newIdErrorEl.hidden = true;
331	        if (newIdInput) {
332	            newIdInput.classList.remove('error');
333	            newIdInput.removeAttribute('aria-invalid');
334	        }
335	
336	        if (!validateRequired(wrapper, ['newWorkspaceId'])) return;
337	
338	        const newId = newIdInput ? newIdInput.value.trim() : '';
339	
340	        if (!WORKSPACE_ID_PATTERN.test(newId)) {
341	            if (newIdErrorEl) {
342	                newIdErrorEl.textContent = 'Must be 2–10 uppercase letters (A-Z only).';
343	                newIdErrorEl.hidden      = false;
344	            }
345	            if (newIdInput) {
346	                newIdInput.classList.add('error');
347	                newIdInput.setAttribute('aria-invalid', 'true');
348	                newIdInput.focus();
349	            }
350	            return;
351	        }
352	
353	        try {
354	            await showConfirm(
355	                'Rename Workspace',
356	                `Rename workspace "${workspace.id}" to "${newId}"? The page will navigate to the new workspace URL.`,
357	            );
358	        } catch {
359	            return;
360	        }
361	
362	        saveBtn.disabled    = true;
363	        saveBtn.textContent = 'Saving…';
364	
365	        try {
366	            await api.workspaces.rename(projectId, workspace.id, newId);
367	            showToast(`Workspace renamed to "${newId}".`, 'success');
368	            const target = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(newId)}`;
369	            if (_router) {
370	                _router.navigate(target);
371	            } else {
372	                location.hash = target;
373	            }
374	        } catch (err) {
375	            showToast(err.message || 'Failed to rename workspace.', 'error');
376	            saveBtn.disabled    = false;
377	            saveBtn.textContent = 'Save';
378	        }
379	    });
380	
381	    return wrapper;
382	}
