694	/**
695	 * Build a health alert section element from a workspace health report.
696	 * Returns `null` when the workspace is healthy (no issues to display).
697	 *
698	 * Fix-action buttons are wired via the `callbacks` argument so the
699	 * caller can inject async handlers that match the surrounding view's
700	 * closure state (project/workspace IDs, toast helper, etc.).
701	 *
702	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
703	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
704	 * @returns {HTMLElement|null}
705	 */
706	function buildHealthAlertSection(healthReport, callbacks) {
707	    if (
708	        !healthReport ||
709	        healthReport.healthy ||
710	        !Array.isArray(healthReport.issues) ||
711	        healthReport.issues.length === 0
712	    ) {
713	        return null;
714	    }
715	
716	    const section = document.createElement('div');
717	    section.className = 'health-alert';
718	
719	    const title = document.createElement('div');
720	    title.className = 'health-alert-title';
721	    title.textContent = 'Workspace health issues detected';
722	    section.appendChild(title);
723	
724	    for (const issue of healthReport.issues) {
725	        const row = document.createElement('div');
726	        row.className = 'health-alert-issue';
727	
728	        const msg = document.createElement('span');
729	        msg.className = 'health-alert-issue__message';
730	        msg.textContent = issue.message;
731	        row.appendChild(msg);
732	
733	        if (issue.fixAction === 'regenerate-workspace-file') {
734	            const actionWrap = document.createElement('span');
735	            actionWrap.className = 'health-alert-issue__action';
736	
737	            const btn = document.createElement('button');
738	            btn.type = 'button';
739	            btn.className = 'btn btn-secondary btn-sm';
740	            btn.textContent = 'Regenerate File';
741	            btn.addEventListener('click', async () => {
742	                btn.disabled = true;
743	                btn.textContent = 'Regenerating\u2026';
744	                try {
745	                    await callbacks.onRegenerate();
746	                } finally {
747	                    btn.disabled = false;
748	                    btn.textContent = 'Regenerate File';
749	                }
750	            });

751	            actionWrap.appendChild(btn);
752	            row.appendChild(actionWrap);
753	        } else if (issue.fixAction === 'setup-workspace') {
754	            const actionWrap = document.createElement('span');
755	            actionWrap.className = 'health-alert-issue__action';
756	
757	            const btn = document.createElement('button');
758	            btn.type = 'button';
759	            btn.className = 'btn btn-secondary btn-sm';
760	            btn.textContent = 'Fix Setup';
761	            btn.addEventListener('click', async () => {
762	                btn.disabled = true;
763	                btn.textContent = 'Setting up\u2026';
764	                try {
765	                    await callbacks.onSetup();
766	                } finally {
767	                    btn.disabled = false;
768	                    btn.textContent = 'Fix Setup';
769	                }
770	            });
771	            actionWrap.appendChild(btn);
772	            row.appendChild(actionWrap);
773	        }
774	        // Issues with an unknown fixAction render the message row without a button.
775	
776	        section.appendChild(row);
777	    }
778	
779	    return section;
780	}
