786	/**
787	 * Render the workspace detail view.
788	 *
789	 * Fetches workspace metadata, project (for the repositories list), polling
790	 * configuration, and initial Git status in parallel. Then starts a polling
791	 * interval that updates badges in-place using the server-configured interval
792	 * (falls back to {@link DEFAULT_POLL_INTERVAL_MS} if the config fetch fails).
793	 *
794	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
795	 * @param {{ id: string, wid: string }} params - Route parameters.
796	 * @returns {function(): void} Cleanup function — clears the polling interval.
797	 *   The router stores and calls this before rendering the next view.
798	 */
799	export function renderWorkspaceDetail(container, params) {
800	    const projectId = params.id;
801	    const wid       = params.wid;
802	
803	    let countdownInterval = null;
804	
805	    // Return the cleanup function immediately so the router can register it
806	    // even if the async bootstrap hasn't resolved yet.
807	    const cleanup = () => {
808	        if (countdownInterval !== null) {
809	            clearInterval(countdownInterval);
810	            countdownInterval = null;
811	        }
812	    };
813	
814	    // Show loading state immediately.
815	    showLoading(container, 'Loading workspace…');
816	
817	    // Kick off parallel data fetch.
818	    Promise.all([
819	        api.workspaces.get(projectId, wid),
820	        api.projects.get(projectId),
821	        api.status.refresh(projectId, wid),
822	        api.config.polling.get().catch(() => null),
823	        api.workspaces.health(projectId, wid).catch(() => null),
824	    ]).then((results) => {
825	        const [rawWorkspace, rawProject, statusMap, pollingConfig, healthReport] = results;
826	        // Guard: if the container was cleared by navigation before we resolved,
827	        // do nothing and let the cleanup function handle the interval.
828	        if (!container.isConnected) return;
829	
830	        const workspace = normaliseWorkspace(rawWorkspace);
831	        const project   = normaliseProject(rawProject);
832	
833	        // Build repo list: [{ repoId, repoName }, …]
834	        const repos = project.repositories.map((r) => ({
835	            repoId:   extractRepoId(r),
836	            repoName: extractRepoName(r),
837	        })).filter((r) => r.repoId !== '');
838	
839	        // Render the view.
840	        container.innerHTML = '';
841	
842	        const isStable = wid === STABLE_WS_ID;
843	
844	        // Resolve the effective poll interval from server config, with fallback.
845	        const pollIntervalMs = (
846	            pollingConfig &&
847	            typeof pollingConfig.gitPollingIntervalSeconds === 'number' &&
848	            Number.isFinite(pollingConfig.gitPollingIntervalSeconds) &&
849	            pollingConfig.gitPollingIntervalSeconds > 0
850	        )
851	            ? pollingConfig.gitPollingIntervalSeconds * 1000
852	            : DEFAULT_POLL_INTERVAL_MS;
853	
854	        // Build status table first to obtain tbody reference for helpers.
855	        const { section: statusSection, tbody } = buildStatusTableSection(repos, statusMap || {}, projectId, wid);
856	
857	        // -------------------------------------------------------------------
858	        // Refresh helpers (referenced by toolbar, polling, and setup)
859	        // -------------------------------------------------------------------
860	
861	        let remainingSeconds = pollIntervalMs / 1000;
862	        let refreshInProgress = false;
863	
864	        // Retry row reference — kept so polling can update/hide it.
865	        let retryRow = null;
866	        let retryHint = null;
867	
868	        // Toolbar elements — built now, wired after helpers are defined.
869	        const toolbar = buildRefreshToolbar();
870	        const progressBar = toolbar.querySelector('.refresh-progress-bar');
871	        const refreshNowBtn = toolbar.querySelector('.refresh-now-btn');
872	
873	        // Health section container — always in DOM between header and toolbar;
874	        // empty when the workspace is healthy.
875	        const healthContainerEl = document.createElement('div');
876	
877	        // Latest health report — kept in sync by renderHealthSection so that
878	        // updateMissingReposRow can exclude repos already covered by health alerts.
879	        let currentHealthReport = healthReport;
880	
881	        /**
882	         * Re-evaluate missing repos after a status update and hide/update
883	         * the retry row accordingly.
884	         *
885	         * Repos flagged by a `repository-not-cloned` health alert (fixAction:
886	         * `setup-workspace`) are excluded from the missing-repos count here
887	         * because the health alert already surfaces a fix button for them.
888	         * This row is therefore reserved for the transient polling-lag case
889	         * where `.git/` is present but status data has not arrived yet.
890	         */
891	        function updateMissingReposRow(freshStatusMap) {
892	            const notClonedIds = new Set(
893	                (currentHealthReport && Array.isArray(currentHealthReport.issues)
894	                    ? currentHealthReport.issues : [])
895	                    .filter((i) => i.fixAction === 'setup-workspace' && i.repositoryId)
896	                    .map((i) => i.repositoryId),
897	            );
898	            const currentMissing = repos.filter(
899	                (r) => !freshStatusMap[r.repoId] && !notClonedIds.has(r.repoId),
900	            );
901	            if (currentMissing.length === 0) {
902	                if (retryRow) {
903	                    retryRow.remove();
904	                    retryRow = null;
905	                    retryHint = null;
906	                }
907	            } else if (retryHint) {
908	                retryHint.textContent = `${currentMissing.length} ${currentMissing.length === 1 ? 'repository has' : 'repositories have'} no data \u2014 clone may have failed.`;
909	            }
910	        }
911	
912	        /**
913	         * Rebuild the health alert container from the given health report.
